// https://www.shadertoy.com/view/4djSRW
vec2 hash22(vec2 p)
{
	vec3 p3 = fract(vec3(p.xyx) * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yzx+33.33);
    return fract((p3.xx+p3.yz)*p3.zy);

}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord*2.0-iResolution.xy)/iResolution.y + iTime * 0.3;
    uv *= 15.0;

    vec2 cellIndex = floor(uv);
    vec2 cellUV = fract(uv);
    float sum = 1000.0;

    for(int i = -1; i <= 1; i++)
    {
        for(int j = -1; j <= 1; j++)
        {
            vec2 sampleIndex = vec2(i,j);
            float dst = distance(cellUV, hash22(cellIndex + sampleIndex) + sampleIndex);
            sum = min(dst, sum);
        }
    }

    fragColor = vec4(vec3(1.0-sum),1.0);
}
